<template><transition name="fade-swap" mode="out-in"><el-tag :key="status" class="status-badge" :class="classes" :type="config.type" effect="light"><el-icon v-if="config.icon"><component :is="config.icon"/></el-icon>{{config.label}}</el-tag></transition></template>
<script setup>import{computed,onBeforeUnmount,ref,watch}from'vue';const props=defineProps({status:{type:String,required:true}});const map={NORMAL:{label:'正常',type:'success',icon:'CircleCheck'},LATE:{label:'迟到',type:'warning',icon:'Timer'},EARLY_LEAVE:{label:'早退',type:'warning',icon:'SwitchButton'},LEAVE:{label:'请假',type:'info',icon:'Document'},ABSENT:{label:'缺勤',type:'danger',icon:'CircleClose'},PENDING:{label:'待审批',type:'warning',icon:'Clock'},APPROVED:{label:'已通过',type:'success',icon:'CircleCheck'},REJECTED:{label:'已拒绝',type:'danger',icon:'CircleClose'},OPEN:{label:'进行中',type:'success',icon:'VideoPlay'},CLOSED:{label:'已关闭',type:'info',icon:'CircleClose'}};const changed=ref(false);let timer;watch(()=>props.status,()=>{clearTimeout(timer);changed.value=true;timer=setTimeout(()=>changed.value=false,520)});onBeforeUnmount(()=>clearTimeout(timer));const config=computed(()=>map[props.status]||{label:props.status,type:'info'}),classes=computed(()=>({'is-pending':props.status==='PENDING','just-approved':changed.value&&props.status==='APPROVED','just-rejected':changed.value&&props.status==='REJECTED'}))</script>
<style scoped>.status-badge{display:inline-flex;align-items:center;gap:4px}.status-badge .el-icon{margin-right:2px}</style>
